# Slashblade JS

Мод, который помогает разработчикам редактировать и создавать рецепты для Slashblade: Resharped с помощью скриптов KubeJS, а также использовать его события.

# Что он может делать?

Вот готовый пример:

```javascript
// приоритет: 0

/* Серверная сторона */

// Когда Slashblade проверяет состояние заряда: если не заряжен, потратить 10 ProudSoul для перехода в заряженное состояние
SlashBladeJSEvents.powerBlade(event => {
    let state = BladeState.of(event.blade)
    let proudsoul = state.proudSoulCount
    if (!event.isPowered() && proudsoul >= 10) {
        state.setProudSoulCount(proudsoul - 10)
        event.setPowered(true)
    }
    event.user.tell("ProudSoul: " + proudsoul) // Сообщить игроку текущее значение ProudSoul
})

// Пользовательский рецепт для Slashblade
ServerEvents.recipes(event => {
    event.recipes.slashblade.slashblade_shaped_recipe("slashblade:slashblade", [
        "ABA",
        "CSC",
        "ABC"
    ], {
        "S": SlashBladeIngredient.of(
            SlashBladeRequestDefinition.name("slashblade:fox_black") // Требуемый базовый клинок
                .killCount(233) // Требование по количеству убийств
                .proudSoul(114514) // Требование по ProudSoul
                .refineCount(10) // Требование по количеству улучшений
                .addEnchantment(SBEnchantmentDefinition.of("minecraft:power", 2)) // Требование по зачарованиям
                .build() // Не забудьте вызвать .build()
        ),
        "A": "minecraft:golden_apple", // Другие материалы (как в ванильных рецептах)
        "B": "#forge:bones",
        "C": "minecraft:cake",
    }, "slashblade:fox_white"/* ID получившегося клинка */)
})

// Создайте свой пользовательский клинок
ServerEvents.highPriorityData(event => {
    let customBlade = SBSlashBladeDefinition.of("kubejs:test_blade", // Ваш ID клинка
        SBRenderDefinition.newInstance() // Свойства рендера
            .effectColor(2039347) // Цвет эффекта клинка (hex RGB в десятичный)
            .standbyRenderType(SBCarryType.DEFAULT) // Положение в ножнах
            .modelName("kubejs:model/named/test_blade.obj") // Путь: ./kubejs/assets/kubejs/model/named/test_blade.obj
            .textureName("kubejs:model/named/test_blade.png") // Путь: ./kubejs/assets/kubejs/model/named/test_blade.png
            .build(), // Не забудьте вызвать .build()
        SBPropertiesDefinition.newInstance()
            .maxDamage(666) // Максимальная прочность
            .baseAttackModifier(999) // Базовый урон от атаки
            .slashArtsType("slashblade:void_slash") // Установить специальную атаку
            .addSpecialEffect("slashblade:wither_edge") // Добавить специальный эффект
            .defaultSwordType([SBSwordType.FIERCEREDGE, SBSwordType.BEWITCHED]) // Установить типы клинков
            .build(), // Не забудьте вызвать .build()
        [ // Зачарования по умолчанию
            SBEnchantmentDefinition.of("minecraft:power", 5),
            SBEnchantmentDefinition.of("minecraft:unbreaking", 10)
        ]
    )

    // Зарегистрировать в игре
    event.addJson("kubejs:slashblade/named_blades/test_blade.json", SBSlashBladeDefinition.toJSON(customBlade))
})
```

